1	// Oracle differential compare. See state_diff.hpp for the policy.
2	#include "state_diff.hpp"
3	
4	#include <cstdio>
5	#include <string>
6	
7	namespace andes_sim {
8	
9	namespace {
10	
11	void cmp(DiffReport& r, const std::string& field, unsigned long long ref,
12	         unsigned long long got) {
13	  ++r.compared;
14	  if (ref != got) r.diffs.push_back({field, ref, got});
15	}
16	
17	}  // namespace
18	
19	DiffReport diff_states(const hybrid_state_v1& ref, const hybrid_state_v1& got) {
20	  DiffReport r;
21	
22	  cmp(r, "magic", ref.magic, got.magic);
23	  cmp(r, "version", ref.version, got.version);
24	  cmp(r, "flags", ref.flags, got.flags);
25	  cmp(r, "hart_id", ref.hart_id, got.hart_id);
26	  cmp(r, "priv", ref.priv, got.priv);
27	  cmp(r, "pc", ref.pc, got.pc);
28	
29	  // mepc/mcause: in the trap-free hybrid ROI they round-trip (L24: restored at
30	  // resume, re-read at drain). mtval/mstatus stay out of scope where they are
31	  // implementation-defined / carry dirty bits (false positives).
32	  cmp(r, "mepc", ref.mepc, got.mepc);
33	  cmp(r, "mcause", ref.mcause, got.mcause);
34	
35	  // Round-trip M-mode CSRs: mscratch (L23) and mtval/mie (L24) are restored at
36	  // resume and re-read at drain, so a trap-free ROI must match the oracle on
37	  // them. mip is excluded: its pending bits are hardware/platform-driven
38	  // (timer/external) and diverge between QEMU's functional clock and vsim's
39	  // cycle clock even with no trap (it still round-trips into the drained
40	  // record, just not the verifier).
41	  cmp(r, "mscratch", ref.mscratch, got.mscratch);
42	  cmp(r, "mtval", ref.mtval, got.mtval);
43	  cmp(r, "mie", ref.mie, got.mie);
44	
45	  for (int i = 0; i < 32; ++i)
46	    cmp(r, "x" + std::to_string(i), ref.gpr[i], got.gpr[i]);
47	
48	  if (ref.flags & HYBRID_FLAG_FP) {
49	    for (int i = 0; i < 32; ++i)
50	      cmp(r, "f" + std::to_string(i), ref.fpr[i], got.fpr[i]);
51	    cmp(r, "fcsr", ref.fcsr, got.fcsr);  // L20: frm + sticky fflags
52	  }
53	
54	  if (ref.flags & HYBRID_FLAG_V) {
55	    cmp(r, "vstart", ref.vstart, got.vstart);
56	    cmp(r, "vtype", ref.vtype, got.vtype);
57	    cmp(r, "vl", ref.vl, got.vl);
58	    cmp(r, "vlenb", ref.vlenb, got.vlenb);
59	    cmp(r, "vxsat", ref.vxsat, got.vxsat);
60	    cmp(r, "vxrm", ref.vxrm, got.vxrm);
61	    cmp(r, "vcsr", ref.vcsr, got.vcsr);
62	
63	    // One compared "field" per vector register; report the first differing
64	    // byte as "v<i>[<byte>]".
65	    for (int i = 0; i < 32; ++i) {
66	      ++r.compared;
67	      const uint8_t* a = &ref.vreg[static_cast<size_t>(i) * HYBRID_VLEN_BYTES_MAX];
68	      const uint8_t* b = &got.vreg[static_cast<size_t>(i) * HYBRID_VLEN_BYTES_MAX];
69	      for (int j = 0; j < HYBRID_VLEN_BYTES_MAX; ++j) {
70	        if (a[j] != b[j]) {
71	          r.diffs.push_back({"v" + std::to_string(i) + "[" +
72	                                 std::to_string(j) + "]",
73	                             a[j], b[j]});
74	          break;
75	        }
76	      }
77	    }
78	  }
79	
80	  // Andes V5 block (v3), minimal slice: mxstatus is the one scalar transported
81	  // so far. It round-trips through the trap-free ROI (restored at resume,
82	  // re-read at drain), so compare it whenever the producer ran on an Andes core
83	  // (FLAG_ANDES). The rest of hybrid_andes_csr (the other scalars + PMA) joins
84	  // this compare set alongside its own transport leg in the completion commit.
85	  if (ref.flags & HYBRID_FLAG_ANDES) {
86	    cmp(r, "mxstatus", ref.andes.mxstatus, got.andes.mxstatus);
87	  }
88	
89	  return r;
90	}
91	
92	void print_diff_report(const DiffReport& r) {
93	  for (const FieldDiff& d : r.diffs)
94	    std::printf("[state-diff] %s: ref=0x%llx got=0x%llx\n", d.field.c_str(),
95	                d.ref, d.got);
96	  if (r.ok()) {
97	    std::printf(
98	        "[state-diff] PASS: %d fields match (counters and passthrough CSRs "
99	        "excluded)\n",
100	        r.compared);
101	  } else {
102	    std::printf("[state-diff] FAIL: %zu mismatch(es) (%d fields compared)\n",
103	                r.diffs.size(), r.compared);
104	  }
105	}
106	
107	}  // namespace andes_sim
